create view public.sim_model_measures with(security_invoker=true) as select v.id as version_id,x->>'id' as id,x->>'name' as name,ord::integer as display_order,x->>'category' as category_id,x->>'mechanism' as description,(x->>'enabled')::boolean as enabled,(x->>'initial_cost')::numeric as initial_cost,(x->>'quarterly_cost')::numeric as quarterly_cost,(x->>'duration_turns')::integer as duration_turns,(x->>'delay_turns')::integer as delay_turns,(x->>'intensity_min')::numeric as intensity_min,(x->>'intensity_max')::numeric as intensity_max,x->'competencies' as competencies,x->'pros' as pros,x->'cons' as cons,x as configuration from public.sim_model_versions v cross join lateral jsonb_array_elements(v.payload#>'{model,measures}') with ordinality a(x,ord);
create view public.sim_model_groups with(security_invoker=true) as select v.id as version_id,x->>'id' as id,x->>'name' as name,ord::integer as display_order,(x->>'initial')::numeric as initial_happiness,(x->>'weight')::numeric as happiness_weight,x->>'engine_slot' as engine_slot,(x->>'visible')::boolean as visible,x->>'note' as criterion,x as configuration from public.sim_model_versions v cross join lateral jsonb_array_elements(v.payload#>'{model,groups}') with ordinality a(x,ord);
create view public.sim_model_variables with(security_invoker=true) as select v.id as version_id,x->>'id' as id,x->>'name' as name,ord::integer as display_order,(x->>'initial')::numeric as initial_value,x->>'unit' as unit,(x->>'visible')::boolean as visible,(x->>'annual_growth')::numeric as annual_growth,x->>'definition' as definition,x as configuration from public.sim_model_versions v cross join lateral jsonb_array_elements(v.payload#>'{model,variables}') with ordinality a(x,ord);
create view public.sim_model_funding_sources with(security_invoker=true) as select v.id as version_id,x->>'id' as id,x->>'name' as name,ord::integer as display_order,x->>'kind' as kind,(x->>'annual_reference')::numeric as annual_reference,(x->>'reference_year')::integer as reference_year,(x#>>'{fiscal_control,base}')::numeric as initial_level,(x#>>'{fiscal_control,min}')::numeric as min_level,(x#>>'{fiscal_control,max}')::numeric as max_level,x->'group_effects' as group_effects,true as signed_adjustments,x as configuration from public.sim_model_versions v cross join lateral jsonb_array_elements(v.payload#>'{model,funding_sources}') with ordinality a(x,ord);
create view public.sim_model_categories with(security_invoker=true) as select v.id as version_id,x->>'id' as id,x->>'name' as name,ord::integer as display_order,x as configuration from public.sim_model_versions v cross join lateral jsonb_array_elements(v.payload#>'{model,categories}') with ordinality a(x,ord);
create view public.sim_model_competencies with(security_invoker=true) as select v.id as version_id,x->>'id' as id,x->>'name' as name,ord::integer as display_order,x->>'description' as description,x as configuration from public.sim_model_versions v cross join lateral jsonb_array_elements(v.payload#>'{model,competencies}') with ordinality a(x,ord);
create view public.sim_model_territories with(security_invoker=true) as select v.id as version_id,x->>'id' as id,x->>'name' as name,ord::integer as display_order,x->>'type' as territorial_scope,(x->>'population_share')::numeric as population_share,(x->>'household_share')::numeric as household_share,x as configuration from public.sim_model_versions v cross join lateral jsonb_array_elements(v.payload#>'{model,territories}') with ordinality a(x,ord);
create view public.sim_model_sources with(security_invoker=true) as select v.id as version_id,x->>'id' as id,x->>'name' as name,ord::integer as display_order,x->>'title' as title,x->>'url' as url,x->>'kind' as kind,x as configuration from public.sim_model_versions v cross join lateral jsonb_array_elements(v.payload#>'{model,sources}') with ordinality a(x,ord);
create view public.sim_model_narratives with(security_invoker=true) as select v.id as version_id,x->>'id' as id,x->>'name' as name,ord::integer as display_order,x->>'variable' as variable_id,x->>'trend' as trend,x->>'text' as text,x as configuration from public.sim_model_versions v cross join lateral jsonb_array_elements(v.payload#>'{model,turn_comments}') with ordinality a(x,ord);
create view public.sim_model_effects with(security_invoker=true) as select v.id as version_id,m->>'id' as measure_id,e->>'id' as id,e->>'target_type' as target_type,e->>'target_id' as target_id,e->>'operation' as operation,(e->>'amount')::numeric as amount,(e->>'delay_turns')::integer as delay_turns,(e->>'maturation_turns')::integer as maturation_turns,(e->>'duration_turns')::integer as duration_turns,(e->>'permanent')::boolean as permanent,e as configuration from public.sim_model_versions v cross join lateral jsonb_array_elements(v.payload#>'{model,measures}') m cross join lateral jsonb_array_elements(m->'effects') e;
create view public.sim_model_demography with(security_invoker=true) as select v.id as version_id,y.key::integer as year,(y.value->>'population')::numeric as population,(y.value->>'births')::numeric as births,(y.value->>'deaths')::numeric as deaths,(y.value->>'immigration')::numeric as immigration,(y.value->>'emigration')::numeric as emigration,y.value as configuration from public.sim_model_versions v cross join lateral jsonb_each(v.payload#>'{model,scenario,demography}') y;
create view public.sim_model_settings with(security_invoker=true) as select id as version_id,payload#>'{model,scenario}' as scenario,payload#>'{model,rules}' as rules,payload#>'{model,prices}' as prices,payload#>'{model,report_settings}' as reports,payload#>'{model,release_history}' as release_history from public.sim_model_versions;
grant select on public.sim_current_model,public.sim_model_measures,public.sim_model_groups,public.sim_model_variables,public.sim_model_funding_sources,public.sim_model_categories,public.sim_model_competencies,public.sim_model_territories,public.sim_model_sources,public.sim_model_narratives,public.sim_model_effects,public.sim_model_demography,public.sim_model_settings to anon,authenticated;
comment on table public.sim_model_versions is 'Canonical simulator data contract. Published payloads are immutable; model views derive from the same JSON. No private review notes.';
comment on view public.sim_current_model is 'Frontend entry point. One published version on the national channel; JavaScript engine performs simulation.';
comment on view public.sim_model_funding_sources is 'Current rates and budget baselines; signed adjustments are supported by the JavaScript engine. Legacy sim_funding is historical only.';
comment on table public.sim_versions is 'Historical SQL simulator generations alpha-1/2/3; current source of truth is sim_model_versions.';
